class RecLog(path: Path) : AutoCloseable {          // facade over the NIO channel
    private val ch = Files.newByteChannel(path, CREATE, APPEND)
    fun append(line: String) {
        ch.write(ByteBuffer.wrap("$line\n".toByteArray()))
    }
    override fun close() = ch.close()
}

RecLog(Path("app.log")).use { it.append("ready") }   // one teardown path

