class Sensor(private val handle: CPointer<sensor_t>) : AutoCloseable {
    companion object {
        fun open(path: String): Sensor =
            Sensor(sensor_open(path.cstr.ptr) ?: error("sensor_open failed"))
    }
    fun read(): Int = sensor_read(handle)
    override fun close() = sensor_close(handle)   // the facade owns the handle
}
